import '@/engines';
import {db} from '@/db';
import {deleteProject} from '@/db/operations';
import {importLocalMedia} from '@/engines/media/operations';
import {runBridgeTool} from '@/services/aiBridge/dispatch';
import {readWorldDocument,saveWorldEra,hideEraDocument} from '@/services/worldEras/store';
import {undoCanvasAction} from '@/engines/board/canvasUndo';
import type {BoardNode} from '@/engines/board/types';
export function boardMediaAssert(value:unknown,message:string):asserts value{if(!value)throw Error(message);}
// Frozen own fixtures from the prior normal reference; byte-for-byte, no generator or external source.
const wav='';
const mp4='';
const bytes=(base64:string)=>Uint8Array.from(atob(base64),c=>c.charCodeAt(0));
export async function boardMediaFixture(suffix:string){
 const projectId='board-media-'+suffix+'-'+crypto.randomUUID(),boardId=projectId+'-board';
 await db.projects.add({id:projectId,title:'Own Board media',description:'',mode:'custom',type:'standalone',status:'draft',color:'#777777',enabledEngines:['board','media'],engineOrder:['board','media'],createdAt:1,updatedAt:1});
 const board={id:boardId,projectId,title:'Own media Board',surface:'slate' as const,viewport:{x:0,y:0,zoom:1},createdAt:1,updatedAt:1};await db.boards.add(board);
 const audio=await importLocalMedia(projectId,new File([bytes(wav)],'Own two tones.wav',{type:'audio/wav'})),video=await importLocalMedia(projectId,new File([bytes(mp4)],'Own colour test.mp4',{type:'video/mp4'}));
 const ref=(id=audio.id)=>({engineId:'media',entityType:'local-media',entityId:id,title:'Cached own media'});
 const action=async(extra:Record<string,unknown>={})=>runBridgeTool('wh_board_canvas_action',{projectId,boardId,action:'reference',ref:ref(),...extra});
 return{projectId,boardId,board,audio,video,ref,action,cleanup:()=>deleteProject(projectId)};
}
export async function testBoardMediaMetadata(){const f=await boardMediaFixture('metadata');try{
 const legacy=await runBridgeTool('wh_board_canvas_get',{projectId:f.projectId,boardId:f.boardId});boardMediaAssert(legacy.ok&&!('mediaAssets'in(legacy.result as object)),'Omitted option changed legacy result');
 const reply=await runBridgeTool('wh_board_canvas_get',{projectId:f.projectId,boardId:f.boardId,includeMedia:true});boardMediaAssert(reply.ok,reply.error??'Metadata read failed');const assets=(reply.result as {mediaAssets?:{id:string;kind:string}[]}).mediaAssets;
 boardMediaAssert(assets?.length===2&&assets.some(x=>x.id===f.video.id&&x.kind==='video')&&assets.some(x=>x.id===f.audio.id&&x.kind==='audio'),'Board metadata does not expose both effective owned media for selection');
 boardMediaAssert(!JSON.stringify(reply.result).includes('blob:')&&!JSON.stringify(reply.result).includes('RIFF')&&!assets.some(x=>'blob'in x),'Metadata leaked media bytes/URL');return['Additive Board metadata lists owned audio and video without Blob, while omitted option preserves legacy response'];
 }finally{await f.cleanup();}}
export async function testBoardMediaReferenceValidation(){const f=await boardMediaFixture('validation');try{
 const current=await f.action();boardMediaAssert(current.ok,'Existing reference positive control failed');await undoCanvasAction({projectId:f.projectId},(current.result as {receiptId:string}).receiptId);
 const original=(await readWorldDocument({projectId:f.projectId},'board',f.boardId))!;const initial=JSON.stringify(original.document);
 for(const patch of [{blob:{}},{kind:'image'}]){await db.localMediaAssets.put({...f.audio,...patch} as never);const reply=await f.action();boardMediaAssert(!reply.ok,'Invalid effective media emitted a successful Board reference batch/receipt');boardMediaAssert(JSON.stringify((await readWorldDocument({projectId:f.projectId},'board',f.boardId))!.document)===initial,'Rejected reference changed document');}
 await db.localMediaAssets.put(f.audio);await saveWorldEra(f.projectId,{id:'past',name:'Past',description:'',revision:0,createdAt:1,updatedAt:1},null);await hideEraDocument({projectId:f.projectId,eraId:'past'},'media',f.audio.id,(await readWorldDocument({projectId:f.projectId,eraId:'past'},'media',f.audio.id))!.version);
 const hidden=await f.action({eraId:'past'});boardMediaAssert(!hidden.ok,'Hidden effective asset fell back to Base');
 return['Existing reference/Undo positive control; invalid Blob/kind rejects before batch/receipt, and hidden era media cannot fall back to Base'];
 }finally{await f.cleanup();}}
export async function testBoardMediaReceipts(){const f=await boardMediaFixture('receipts');try{
 const call=async(extra:Record<string,unknown>={})=>{const r=await f.action(extra);boardMediaAssert(r.ok,r.error??'Reference failed');return r.result as {receiptId:string;addedOrUpdated:string[]}};
 let aborted='';try{await db.transaction('rw',db.tables,async()=>{aborted=(await call()).receiptId;throw Error('own outer abort')});}catch{/* deliberate outer rollback */}
 boardMediaAssert(await db.boardNodes.where('boardId').equals(f.boardId).count()===0,'Outer abort persisted reference');let rejected=false;try{await undoCanvasAction({projectId:f.projectId},aborted);}catch{rejected=true;}boardMediaAssert(rejected,'Outer abort kept receipt');
 const c=await call();await undoCanvasAction({projectId:f.projectId},c.receiptId);rejected=false;try{await undoCanvasAction({projectId:f.projectId},c.receiptId);}catch{rejected=true;}boardMediaAssert(rejected,'Receipt reused');
 const old=await call(),later=await call({ref:f.ref(f.video.id)});rejected=false;try{await undoCanvasAction({projectId:f.projectId},old.receiptId);}catch{rejected=true;}boardMediaAssert(rejected&&await db.boardNodes.get(later.addedOrUpdated[0]),'Stale Undo lost later node');
 await saveWorldEra(f.projectId,{id:'past',name:'Past',description:'',revision:0,createdAt:1,updatedAt:1},null);const base=(await readWorldDocument({projectId:f.projectId},'board',f.boardId))!.version,era=await call({eraId:'past'});await undoCanvasAction({projectId:f.projectId,eraId:'past'},era.receiptId);boardMediaAssert((await readWorldDocument({projectId:f.projectId},'board',f.boardId))!.version===base,'Era Undo changed Base');
 boardMediaAssert((await db.localMediaAssets.get(f.audio.id))!.blob.size===f.audio.size,'Node Undo changed library bytes');return['Normal canvas reference receipts: outer abort, one-use, stale aggregate CAS and named-era Undo preserve library and Base'];
 }finally{await f.cleanup();}}
export type BoardMediaNode=BoardNode;

/** Real executor and filesystem audit/RPC provided by the existing native setup, no network listener. */
export async function testBoardMediaNativeAudit(){
 const bridge=(window as unknown as{__iconsAudit?:{invoke:(op:string,payload?:unknown)=>Promise<unknown>}}).__iconsAudit;boardMediaAssert(bridge,'Use the approved native audit binding for this export');
 const f=await boardMediaFixture('native');type Outcome={ok:boolean;result?:{receiptId:string;addedOrUpdated:string[];undone?:boolean};auditIndex?:number;code?:string;error?:string};
 const execute=async(tool:string,args:Record<string,unknown>)=>await bridge.invoke('execute',{tool,args:{projectId:f.projectId,...args}})as Outcome;
 try{
  for(const eraId of [undefined,'past']){
   if(eraId)await saveWorldEra(f.projectId,{id:eraId,name:'Past',description:'',revision:0,createdAt:1,updatedAt:1},null);
   const scope={projectId:f.projectId,eraId},before=(await readWorldDocument(scope,'board',f.boardId))!.version;
   const created=await execute('wh_board_canvas_action',{boardId:f.boardId,eraId,action:'reference',ref:f.ref(),expectedVersion:before});boardMediaAssert(created.ok&&created.result&&Number.isInteger(created.auditIndex),'Real executor reference did not emit audit index: '+JSON.stringify(created));
   const record=await bridge.invoke('record',created.auditIndex)as{before:Record<string,unknown>;eraId?:string};boardMediaAssert(record?.before.__boardCanvasReceipt===created.result.receiptId&&Object.keys(record.before).length===1&&record.eraId===eraId,'Filesystem audit does not contain real scoped opaque receipt');
   const undone=await bridge.invoke('undo',created.auditIndex)as Outcome;boardMediaAssert(undone.ok&&undone.result?.undone,'Actual audit-index RPC Undo failed: '+JSON.stringify(undone));boardMediaAssert(!(await readWorldDocument(scope,'board',f.boardId))!.document.children.boardNodes.some(x=>x.id===created.result!.addedOrUpdated[0]),'Native Undo kept reference');
   const duplicate=await bridge.invoke('undo',created.auditIndex)as Outcome;boardMediaAssert(!duplicate.ok,'Native audit Undo reused');
  }
  const old=await execute('wh_board_canvas_action',{boardId:f.boardId,action:'reference',ref:f.ref()}),later=await execute('wh_board_canvas_action',{boardId:f.boardId,action:'reference',ref:f.ref(f.video.id)});boardMediaAssert(old.ok&&later.ok,'Native stale controls failed');boardMediaAssert(!(await bridge.invoke('undo',old.auditIndex)as Outcome).ok,'Native Undo overwrote later canvas edit');
  await db.localMediaAssets.put({...f.audio,blob:{}}as never);const invalid=await execute('wh_board_canvas_action',{boardId:f.boardId,action:'reference',ref:f.ref()});boardMediaAssert(!invalid.ok,'Real executor admitted invalid Blob');
  return['Real executor→IPC/renderer→filesystem audit→RPC Undo: opaque session receipt Base/era, duplicate/stale refusals and invalid effective Blob; no listener or stdio claim'];
 }finally{await f.cleanup();}
}
